				method: 'POST',
				headers: {
					'Content-Type': 'application/json'
				},
				body: JSON.stringify({ fileUrl, mimeType })
			});

			if (!response.ok) {
				const errorText = await response.text();
				throw new Error(`OCR API error: ${response.status} - ${errorText}`);
			}

			const result = await response.json();
			return result.data;
		} catch (e) {
			console.error('OCR extraction failed:', e);
			return null;
		}
	}

	async list(
		sort: 'transaction_date' | 'merchant_name' | 'total_amount' = 'transaction_date',
		direction: 'asc' | 'desc' = 'desc'
	) {
		return withRetry(async () => {
			const user = (await this.supabase.auth.getUser()).data.user;
			if (!user) throw new Error('Not authenticated');

			console.log('[ReceiptService] Fetching receipts for user:', user.id);

			// Check family memberships for debugging
			const { data: familyMemberships, error: fmError } = await this.supabase
				.from('family_members')
				.select('*')
				.eq('user_id', user.id);
			console.log('[ReceiptService] Family memberships:', familyMemberships, fmError);

			// Don't filter by user_id - let RLS policies handle access based on family membership
			// This allows family members to see each other's receipts
			const { data, error } = await this.supabase
				.from('receipts')
				.select('*')
				.order(sort, { ascending: direction === 'asc' });
