		'credit_card_last_4',
		'currency',
		'exchange_rate_to_cad',
		'matched_transaction_id',
		'suspicious_date',
		'split_group_id'
	]);

	async update(id: string, patch: ReceiptInsert) {
		return withRetry(async () => {
			// Strip non-editable fields (id, user_id, created_at, etc.) to prevent
			// Supabase 400 errors from invalid values being sent in the update.
			const safePatch: ReceiptInsert = {};
			const source = patch as Record<string, unknown>;
			const target = safePatch as Record<string, unknown>;
			for (const key of Object.keys(patch)) {
