import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { processOcrFromUrl } from '$lib/server/ocrProcessor';

/**
 * POST /api/ocr/extract
 *
 * Extracts receipt data from a file URL using OCR
 * This endpoint expects the file to already be uploaded to storage
 *
 * Request body (JSON):
 * - fileUrl: Public URL of the file in storage
 * - mimeType: MIME type of the file
 *
 * Response:
 * - 200: { success: true, data: ReceiptExtract, mimeType: string }
 * - 400: Validation error
 * - 500: Processing error
 */
export const POST: RequestHandler = async ({ request }) => {
	try {
		const body = await request.json();
		const { fileUrl, mimeType } = body;

		// Validate inputs
		if (!fileUrl || typeof fileUrl !== 'string') {
			throw error(400, 'fileUrl is required and must be a string');
		}

		if (!mimeType || typeof mimeType !== 'string') {
			throw error(400, 'mimeType is required and must be a string');
		}

		// Process OCR
		const result = await processOcrFromUrl(fileUrl, mimeType);

		if (!result.success) {
			throw error(500, result.error || 'OCR processing failed');
		}

		return json({
			success: true,
			data: result.data,
			mimeType: result.mimeType
		});
	} catch (err) {
		console.error('OCR extract API error:', err);

		// Re-throw SvelteKit errors
		if (err && typeof err === 'object' && 'status' in err) {
			throw err;
		}

		// Handle other errors
		const message = err instanceof Error ? err.message : 'Unknown error occurred';
		throw error(500, `OCR extraction failed: ${message}`);
	}
};

